const IMG={en:{cover:"data:image/jpeg;base64,",card:"data:image/jpeg;base64,",hint:"Tap the cover to open"},
           mr:{cover:"data:image/jpeg;base64,",card:"data:image/jpeg;base64,",hint:"पत्रिका उघडण्यासाठी स्पर्श करा"}};
const SONG = "data:audio/mpeg;base64,"; // Vaaru song (mp3 data) — empty until provided

const $=s=>document.querySelector(s);
let lang="en",audio=null,muted=false,busy=false,started=false;
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;

if(SONG){
  audio=new Audio(SONG);
  audio.loop=true;
  audio.preload="none";
  audio.volume=0;
}

function play(){
  if(!audio)return;
  audio.play().then(()=>{
    let v=audio.volume;
    const fade=setInterval(()=>{
      if(!audio){clearInterval(fade);return;}
      v=Math.min(.8,v+.04);
      audio.volume=muted?0:v;
      if(v>=.8)clearInterval(fade);
    },120);
  }).catch(()=>{
    // Browsers may block playback; the invitation remains fully usable without music.
  });
}

function setLang(l){
  if(!IMG[l])return;
  lang=l;
  $('#coverImg').src=IMG[l].cover;
  $('#cardImg').src=IMG[l].card;
  $('#cardImg').hidden=(l==='mr');
  $('#mrCard').hidden=(l!=='mr');
  $('#hint').textContent=IMG[l].hint;
  document.documentElement.lang=l==='mr'?'mr':'en';
  document.querySelectorAll('[data-sw]').forEach(b=>{
    b.setAttribute('aria-pressed',String(b.dataset.sw===l));
  });
}

function closeBook(){
  const stage=$('#stage');
  stage.classList.remove('opening','shown');
  $('#cover').focus({preventScroll:true});
}

function start(l){
  if(started)return;
  started=true;
  setLang(l);
  play();
  $('#splash').classList.add('hide');
  $('#loader').classList.add('on');
  window.setTimeout(()=>$('#loader').classList.add('zoom'),reducedMotion?0:2000);
  window.setTimeout(()=>{
    $('#stage').classList.add('on');
    $('#bar').classList.add('on');
    $('#loader').classList.remove('on');
    $('#cover').focus({preventScroll:true});
  },reducedMotion?50:3300);
}

function openBook(){
  const stage=$('#stage');
  if(busy||stage.classList.contains('opening'))return;
  busy=true;
  const flash=$('#flash');
  flash.classList.remove('go-flash');
  void flash.offsetWidth;
  if(!reducedMotion)flash.classList.add('go-flash');
  window.setTimeout(()=>stage.classList.add('opening'),reducedMotion?0:350);
  window.setTimeout(()=>{
    stage.classList.add('shown');
    busy=false;
    $('#card').focus({preventScroll:true});
  },reducedMotion?20:1100);
}

document.querySelectorAll('[data-lang]').forEach(button=>{
  button.type='button';
  button.addEventListener('click',()=>start(button.dataset.lang));
});
$('#cover').addEventListener('click',openBook);
$('#cardImg').addEventListener('click',closeBook);
$('#mrClose').addEventListener('click',closeBook);

document.querySelectorAll('[data-sw]').forEach(button=>{
  button.type='button';
  button.addEventListener('click',()=>{
    if(button.dataset.sw===lang)return;
    closeBook();
    window.setTimeout(()=>setLang(button.dataset.sw),reducedMotion?0:500);
  });
});

$('#mute').addEventListener('click',()=>{
  muted=!muted;
  if(audio)audio.volume=muted?0:.8;
  $('#mute').style.opacity=muted?'.45':'1';
  $('#mute').setAttribute('aria-pressed',String(muted));
  $('#mute').setAttribute('aria-label',muted?'Unmute music':'Mute music');
});

document.addEventListener('keydown',event=>{
  if(event.key==='Escape' && $('#stage').classList.contains('shown'))closeBook();
});

// Gold-dust background. Scale the canvas for sharper rendering on high-density screens.
const cv=$('#dust');
const cx=cv.getContext('2d');
let W=0,H=0,DPR=1,P=[];
function rs(){
  DPR=Math.min(window.devicePixelRatio||1,2);
  W=window.innerWidth;
  H=window.innerHeight;
  cv.width=Math.round(W*DPR);
  cv.height=Math.round(H*DPR);
  cv.style.width=W+'px';
  cv.style.height=H+'px';
  cx.setTransform(DPR,0,0,DPR,0,0);
}
rs();
window.addEventListener('resize',rs,{passive:true});

for(let i=0;i<55;i++){
  P.push({x:Math.random(),y:Math.random(),r:Math.random()*2+.6,s:Math.random()*.0006+.0002,a:Math.random()*6});
}

if(cx && !reducedMotion){
  (function dust(){
    cx.clearRect(0,0,W,H);
    for(const p of P){
      p.y-=p.s;
      p.a+=.02;
      if(p.y<-.02){p.y=1.02;p.x=Math.random();}
      cx.globalAlpha=.35+.35*Math.sin(p.a);
      cx.fillStyle='#f6dca0';
      cx.beginPath();
      cx.arc(p.x*W,p.y*H,p.r,0,Math.PI*2);
      cx.fill();
    }
    cx.globalAlpha=1;
    requestAnimationFrame(dust);
  })();
}
